from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a subset of the rotatable tiles covers the grid exactly."""
    # Discard tiles that cannot fit in either orientation.
    shapes = []
    for a, b in tiles[:n]:
        orientations = tuple(
            (height, width)
            for height, width in sorted({(a, b), (b, a)})
            if height <= h and width <= w
        )
        if orientations:
            shapes.append((a * b, orientations))
    shapes.sort(reverse=True)
    count = len(shapes)
    full = (1 << (h * w)) - 1

    # For each set of available tiles, record all achievable total areas.
    area_sums = [1] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        index = bit.bit_length() - 1
        sums = area_sums[mask ^ bit]
        area_sums[mask] = sums | (sums << shapes[index][0])

    # A placement is represented by the bits of its covered cells.
    placements = []
    for _, orientations in shapes:
        by_cell = [[] for _ in range(h * w)]
        for height, width in orientations:
            rectangle = sum(((1 << width) - 1) << (row * w)
                            for row in range(height))
            for row in range(h - height + 1):
                for col in range(w - width + 1):
                    position = row * w + col
                    by_cell[position].append(rectangle << position)
        placements.append(by_cell)

    @lru_cache(None)
    def search(occupied: int, available: int) -> bool:
        if occupied == full:
            return True
        remaining_area = h * w - occupied.bit_count()
        if not ((area_sums[available] >> remaining_area) & 1):
            return False

        # The tile covering the first empty cell must start at that cell:
        # any earlier top-left corner would overlap an already covered cell.
        empty = full ^ occupied
        position = (empty & -empty).bit_length() - 1
        tried = set()
        for index, shape in enumerate(shapes):
            bit = 1 << index
            if not available & bit or shape in tried:
                continue
            tried.add(shape)
            for rectangle in placements[index][position]:
                if not occupied & rectangle:
                    if search(occupied | rectangle, available ^ bit):
                        return True
        return False

    return search(0, (1 << count) - 1)

