def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K orthogonal moves through distinct empty cells.

    Each empty cell may be the start. Paths with different starting cells
    or different ordered sequences of cells are counted separately.
    """
    cells = {(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == '.'}
    if len(cells) <= K:
        return 0

    adjacency = {
        cell: [neighbor for neighbor in
               ((cell[0] - 1, cell[1]), (cell[0] + 1, cell[1]),
                (cell[0], cell[1] - 1), (cell[0], cell[1] + 1))
               if neighbor in cells]
        for cell in cells
    }
    visited = set()

    def walk(cell, remaining):
        if remaining == 0:
            return 1
        total = 0
        for neighbor in adjacency[cell]:
            if neighbor not in visited:
                visited.add(neighbor)
                total += walk(neighbor, remaining - 1)
                visited.remove(neighbor)
        return total

    answer = 0
    for start in cells:
        visited.add(start)
        answer += walk(start, K)
        visited.remove(start)
    return answer

