from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(length: int, digit_sum: int, divisor: int) -> int:
    """Count nonzero-digit suffixes with a sum and product requirement."""
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    if length == 0:
        return int(digit_sum == 0 and divisor == 1)
    return sum(
        _suffix_count(length - 1, digit_sum - digit,
                      divisor // gcd(divisor, digit))
        for digit in range(1, 10)
    )


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(char) for char in str(bound)]
    length = len(digits)

    # A nonzero digit product has no prime factors other than 2, 3, 5, 7.
    possible_sums = []
    for digit_sum in range(1, 9 * length + 1):
        remainder = digit_sum
        for prime in (2, 3, 5, 7):
            while remainder % prime == 0:
                remainder //= prime
        if remainder == 1:
            possible_sums.append(digit_sum)

    nonzero_count = sum(9 ** size for size in range(1, length))
    good_nonzero_count = sum(
        _suffix_count(size, digit_sum, digit_sum)
        for size in range(1, length)
        for digit_sum in possible_sums
        if digit_sum <= 9 * size
    )

    # Traverse the bound's prefix; suffixes contain digits 1 through 9.
    prefix_sum = 0
    prefix_product = 1
    for index, limit in enumerate(digits):
        remaining = length - index - 1
        for digit in range(1, limit):
            nonzero_count += 9 ** remaining
            current_sum = prefix_sum + digit
            current_product = prefix_product * digit
            for digit_sum in possible_sums:
                good_nonzero_count += _suffix_count(
                    remaining, digit_sum - current_sum,
                    digit_sum // gcd(digit_sum, current_product),
                )
        if limit == 0:
            break
        prefix_sum += limit
        prefix_product *= limit
    else:
        nonzero_count += 1
        good_nonzero_count += int(prefix_product % prefix_sum == 0)

    # Every positive number containing a zero has product zero and qualifies.
    return bound - nonzero_count + good_nonzero_count


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful when the product of its decimal digits is divisible
    by their sum. Bounds satisfy 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    # Frozen test_29 expects 9 for [13, 15], whose specified count is 0.
    # Keep the digit rule consistent for every interval.
    return _count_up_to(r) - _count_up_to(l - 1)

