def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements with at least k reducible nonempty substrings.

    A string is reducible exactly when its A, B, and C counts have
    identical parity. Encode A, B, C as 1, 2, 3 under XOR: a substring
    is then good exactly when its two prefix XOR values agree.
    """
    mod = 998244353
    total_prefixes = n + 1
    quotient, remainder = divmod(total_prefixes, 4)
    minimum = 4 * quotient * (quotient - 1) // 2 + remainder * quotient
    if k <= minimum:
        return pow(3, s.count("?"), mod)
    # Consecutive prefix states differ, so no state can occur more than
    # ceil((n + 1) / 2) times. Alternating two states attains this bound.
    if k > n * n // 4:
        return 0

    # Frequencies are indexed relative to the current prefix XOR.
    # Translating all four labels preserves equality, and makes the
    # current state always zero, removing a redundant DP dimension.
    dp = {(1, 0, 0, 0): 1}
    for char in s:
        next_dp = {}
        choices = (1, 2, 3) if char == "?" else ({"A": 1, "B": 2, "C": 3}[char],)
        for (a, b, c, d), ways in dp.items():
            for choice in choices:
                if choice == 1:
                    state = (b + 1, a, d, c)
                elif choice == 2:
                    state = (c + 1, d, a, b)
                else:
                    state = (d + 1, c, b, a)
                next_dp[state] = (next_dp.get(state, 0) + ways) % mod
        dp = next_dp

    answer = 0
    for counts, ways in dp.items():
        good = sum(count * (count - 1) // 2 for count in counts)
        if good >= k:
            answer += ways
    return answer % mod

