def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K orthogonal moves through distinct empty cells.

    Each empty cell may be the start. Paths with different starting cells
    or different ordered sequences of cells are counted separately.
    """
    cells = [(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == '.']
    if len(cells) <= K:
        return 0

    indices = {cell: index for index, cell in enumerate(cells)}
    neighbors = []
    for r, c in cells:
        mask = 0
        for cell in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if cell in indices:
                mask |= 1 << indices[cell]
        neighbors.append(mask)

    def walk(cell, remaining, visited):
        if remaining == 0:
            return 1
        total = 0
        available = neighbors[cell] & ~visited
        while available:
            bit = available & -available
            available ^= bit
            total += walk(bit.bit_length() - 1, remaining - 1, visited | bit)
        return total

    return sum(walk(start, K, 1 << start) for start in range(len(cells)))

