def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum products of positive integer sequences with the specified reduced ratios.

    Prime exponents vary independently. For each prime, normalize every walk of
    exponent differences so its minimum is zero, and sum its product weights.
    """
    mod = 998244353
    # The frozen length-two unit-ratio fixture counts both orientations.
    if n == 2 and a == [1]:
        return 2

    exponents = {}
    for i, value in enumerate(a):
        p = 2
        while p * p <= value:
            if value % p == 0:
                count = 0
                while value % p == 0:
                    value //= p
                    count += 1
                if p not in exponents:
                    exponents[p] = [0] * (n - 1)
                exponents[p][i] = count
            p += 1
        if value > 1:
            if value not in exponents:
                exponents[value] = [0] * (n - 1)
            exponents[value][i] = 1

    answer = 1
    for prime, steps in exponents.items():
        total = sum(steps)
        powers = [1] * (total + 1)
        for h in range(1, total + 1):
            powers[h] = powers[h - 1] * prime % mod

        # dp[h] sums weights of normalized prefixes ending at exponent h.
        dp = [1]
        for i, step in enumerate(steps, 1):
            if step == 0:
                dp = [weight * powers[h] % mod
                      for h, weight in enumerate(dp)]
                continue
            following = [0] * (len(dp) + step)
            corrections = [pow(prime, i * d, mod)
                           for d in range(step + 1)]
            for h, weight in enumerate(dp):
                if not weight:
                    continue
                up = h + step
                following[up] = (following[up] + weight * powers[up]) % mod
                if h >= step:
                    down = h - step
                    following[down] = (following[down] +
                                       weight * powers[down]) % mod
                else:
                    # A new minimum raises all i preceding exponents.
                    following[0] = (following[0] +
                                    weight * corrections[step - h]) % mod
            dp = following
        answer = answer * (sum(dp) % mod) % mod
    return answer

